/**
 * The Rejected King
 * -----------------
 * Saul disobeys at Gilgal and Samuel says: to obey is better than sacrifice, and the kingdom is torn from him. Stage: a battlefield at dusk, a king in torn robes, a prophet with a torn cloak, the sound of the sheep and the cattle; a kingdom ending, a door closing.
 *
 * Palette 0x1a2a1a → 0x060402 · light: ember · hero: sheep
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./samuel-kit.js.
 */

import { THREE, createScene, column, throne, house, sheep, person } from './samuel-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 56430048, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x142014 });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x111b11 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, -11, 0, -14, 1.0 + W.r() * 0.3, { mud: 0x060402 });
    house(W, group, 18, 0, -8, 0.8 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the sheep */
    sheep(W, group, 0, 0, 0, 0, 1.3);
    W.disc([0, 4, -10], 4, 0x223722, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.54, s: 1.18 });

    return W.finish();
}

export default { build };
